import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>从现代网站上下载的 AVIF 图片，常常在你需要的软件里打不开。转成 JPG 不到一分钟就能搞定，转出来的文件到处都能用。</p>\n<p>唯一有点讲究的是透明度，唯一的要求是一台能解码 AVIF 的现代浏览器。</p>\n<p>这篇指南一步一步带你走完流程，让你第一次转换就出干净的结果。</p>\n<h2 id=\"before-you-start\">开始之前：先检查浏览器</h2>\n<p>你需要一台能原生解码 AVIF 的现代浏览器。新版 Chrome、Edge、Firefox 和 Safari 都行，浏览器太老就先更新。</p>\n<p>在设备上找到 AVIF 文件。它们通常来自下载文件夹，网站在你不知情的情况下提供了 AVIF 而不是 JPG。</p>\n<p>检查图片有没有透明部分。照片通常没有，标志和贴纸可能有，透明区域需要一个填充色。</p>\n<p>单个文件最大支持 25MB，高清下载图和相机直出的照片都不用提前处理，直接就能转。</p>\n<h2 id=\"step-1-open-tool\">第 1 步：打开 AVIF 转 JPG 工具</h2>\n<p>在浏览器里打开 <a href=\"/zh/avif-zhuan-jpg/\">AVIF 转 JPG 工具</a>。Windows、Mac、Linux、ChromeOS、安卓和 iOS 都能用。</p>\n<p>页面上有上传区、填充色选择器和画质滑块这三个控件，整个操作就是它们了。</p>\n<p>不用注册账号，文件也不会上传。转换就在你的设备上完成，私人图片和下载文件也不用担心外泄。</p>\n<p>用手机的话，直接在手机浏览器里打开这个页面就行。点一下上传区，就能从下载文件夹或相册里选 AVIF 文件。</p>\n<h2 id=\"step-2-upload\">第 2 步：上传 AVIF 文件</h2>\n<p>把 AVIF 文件拖到上传区，或者点一下打开文件选择器。一次选多个文件，就能批量转换。</p>\n<p>每个文件都会显示为一张卡片，带有缩略图、尺寸和文件大小。快速扫一眼，就能确认传对了文件，没有多余的混进来。</p>\n<p>某个文件加载失败，可能是浏览器解码不了 AVIF。把浏览器更新到最新版，再试一次。</p>\n<p>电脑上还能用 Ctrl+V 直接粘贴剪贴板里的图片。AVIF 图片在别的软件里复制好之后，这个办法很方便。</p>\n<h2 id=\"step-3-matte-colour\">第 3 步：选填充色</h2>\n<p>点填充色选择器，给透明区域选一个填充颜色。默认白色，适合大多数用途。</p>\n<p>深色设计就选黑色，或者直接输入十六进制颜色码，精确匹配某个网站的背景色。背景对上了，标志看起来就像本来长在那里一样。</p>\n<p>如果你的 AVIF 没有透明部分，这个设置不起任何作用。照片不管选什么颜色，都会原样通过。</p>\n<p>转换后看一眼标志卡片，填充效果一目了然。颜色错了马上就能发现，改了再转一次就行。</p>\n<h2 id=\"step-4-quality\">第 4 步：设置画质滑块</h2>\n<p>大多数 AVIF 照片用 85% 的 JPG 画质最合适。照片看着干净，文件大小合理，损失肉眼看不见。</p>\n<p>要拿去打印的图片，用 90% 或更高的画质。打印会放大屏幕上看不出的瑕疵，单张重要图片多占一点空间完全值得。</p>\n<p>要发给有大小限制的表单时，从 85% 开始逐步往下调。每调一步看一下大小，文件刚好符合要求就停下。</p>\n<p>AVIF 照片常常画质非常高，所以转换时很耐折腾。85% 的 JPG 在正常观看尺寸下，通常看起来和 AVIF 一模一样。</p>\n<h2 id=\"step-5-convert-preview\">第 5 步：转换并预览结果</h2>\n<p>点“转换”按钮。每个文件独立转换，进度可以一张卡片一张卡片地看。</p>\n<p>每张卡片都会显示转换后的 JPG 大小和原来 AVIF 大小的对比。JPG 更大是正常的，因为 AVIF 更高效。</p>\n<p>点卡片上的“对比”可以并排检查结果。拖动分隔线，检查人脸、文字和颜色。</p>\n<p>如果结果看着发软，把画质提高 5 个点再转一次。原 AVIF 还留在队列里，不用重新上传。</p>\n<h2 id=\"step-6-download\">第 6 步：下载 JPG 文件</h2>\n<p>点单张卡片上的“下载”，就能保存这一张 JPG。文件名保持原名，只把后缀换成 .jpg。</p>\n<p>批量转换时，点“全部下载”可以拿到一个 ZIP，里面装着所有转好的 JPG。这比一张一张下载快得多。</p>\n<p>用之前先检查一遍下载好的文件。在看图软件里打开一张 JPG，确认显示正常，也确认它能在你需要的软件里打开。</p>\n<p>原 AVIF 文件也留着。它们是你手里画质最好的版本，以后需要别的格式还能再转。</p>\n<ol>\n<li>打开 AVIF 转 JPG 工具，上传 AVIF 文件。</li>\n<li>给透明区域选一个填充色。</li>\n<li>把画质滑块设到 85%。</li>\n<li>转换后用对比功能预览，再下载 JPG。</li>\n</ol>\n<h2 id=\"converting-a-batch\">一次转换多个 AVIF 下载文件</h2>\n<p>在文件选择器里一次选中多个 AVIF 文件。它们会全部进入队列，点一下就能全部转成 JPG。</p>\n<p>整批用同一个填充色和画质。同一份文档或同一个项目里的图片，保持一致才专业。</p>\n<p>批量运行时留意错误提示。浏览器解码不了的文件会显示警告，更新浏览器通常就能解决。</p>\n<p>批量下载的 ZIP 解压到一个新文件夹里。转好的 JPG 和原 AVIF 混在一个文件夹里，以后很容易搞混。</p>\n<h2 id=\"fixing-problems\">常见问题怎么修</h2>\n<p>转换失败了，先更新浏览器。解码 AVIF 需要较新的版本，老浏览器根本读不了这些文件。</p>\n<p>JPG 看着发灰，可能是 HDR 或宽色域颜色在转换时偏移了。在任何修图软件里稍微调一下饱和度，就能恢复那种鲜艳感。</p>\n<p>透明 AVIF 转出来带个黑框，说明填充色是黑色或者没设置。改成白色或你的页面颜色，再转一次就行。</p>\n<p>第一次结果看着不对，就微调设置再试一次。原件还留在队列里，第二次尝试只花几秒钟。</p>\n<h2 id=\"after-converting\">转换之后：接下来做什么</h2>\n<p>JPG 是用来交表单的，先看大小限制再上传。85% 画质转出来的 JPG 可能超过 2MB 的上限，需要的话还得压缩一下。</p>\n<p>网站要求精确大小时，用<a href=\"/zh/tupian-yasuo-dao-100kb/\">100KB 压缩器</a>或<a href=\"/zh/mubiao-wenjian-daxiao-yasuo/\">目标文件大小压缩器</a>。先转换、再压缩，这个顺序不能反。</p>\n<p>JPG 是用来放网站的，可以考虑再转成 WebP。<a href=\"/zh/jpg-zhuan-webp/\">JPG 转 WebP 工具</a>能把新转出来的 JPG 再缩小，适合上网使用。</p>\n<p>JPG 是用来打印的，画质保持在 90% 以上。打印会放大压缩瑕疵，高画质 JPG 是最稳妥的选择。</p>\n<h2 id=\"mobile-tips\">手机和平板上的小技巧</h2>\n<p>手机上点一下上传区，从下载文件夹或相册里选 AVIF 文件。转换就在手机上完成，JPG 会下载到你的设备里。</p>\n<p>手机上批量别贪多，大 AVIF 文件在手机处理器上解码比较慢。一次转十张左右比较舒服。</p>\n<p>下载的文件在手机的“下载”文件夹里。iPhone 在“文件”应用里找，安卓在文件管理器里找。</p>\n<p>要转一大批下载图，还是用电脑。更快的处理器和更大的屏幕，处理很多文件要轻松得多。</p>\n<h2 id=\"avif-for-form\">为表单转换 AVIF</h2>\n<p>上传表单只接受 JPG 和 PNG，AVIF 文件会直接被弹回来。上传前先转成 JPG，再看一下表单的具体规则。</p>\n<p>图片用 85% 画质转成 JPG。照片看着干净，文件大小合理，表单收起来毫无问题。</p>\n<p>转换后看一下文件大小限制。上传上限 2MB 的表单可能拒绝一张 4MB 的 JPG，太大了就用 100KB 或 200KB 工具压缩一下。</p>\n<p>尺寸也要看，不只是格式。表单要求特定像素尺寸时，格式对了、形状不对的图片同样会被拒绝。</p>\n<p>尽早上传转换好的图片，别拖到截止日期。最后一刻才转换，出了问题没有时间修，提前上传还有机会再试一次。</p>\n<h2 id=\"avif-for-email\">为邮件转换 AVIF</h2>\n<p>邮箱客户端显示 JPG 很可靠，AVIF 的支持却不一致。AVIF 附件可能显示为破损图片，放在商务邮件里显得很不专业。</p>\n<p>添加附件之前，先把 AVIF 转成 JPG。JPG 在所有邮箱客户端、所有设备上都能正确显示，邮件完整送达。</p>\n<p>邮件图片的画质保持在 85%。照片看着干净，文件小到能直接发送，对方看到的图片和你的一样。</p>\n<p>几张图片一起发时，批量转换后再把 JPG 一起附上。一组 AVIF 文件转成 JPG 后，既小得多，兼容性也好得多。</p>\n<p>发送前看一下总大小。快速扫一眼附件大小，就能避免那种以为邮件发出去了、结果却收到退信的尴尬。</p>\n<h2 id=\"avif-for-presentation\">为演示文稿转换 AVIF</h2>\n<p>演示幻灯片里的图片要在演示电脑上打开，AVIF 在老机器上可能失败。先转成 JPG，幻灯片在哪里都能用。</p>\n<p>放进演示文稿之前，先把 AVIF 图片用 85% 到 90% 画质转成 JPG。JPG 在所有版本的 PowerPoint 里都能干净地嵌入。</p>\n<p>图片多的文稿，整批一起转。批量转换几分钟就能完成，转好的 JPG 直接拖进幻灯片就行。</p>\n<p>转换后看一下整份文稿的大小。超过 50MB 的文稿发邮件或上传都费劲，文件太大就先压缩一下图片。</p>\n<p>演讲前先在演示电脑上测试一下文稿。笔记本上看着正常的幻灯片，在老机器上可能显示破损图片，提前测试就能发现。</p>\n<h2 id=\"avif-for-client\">为客户转换 AVIF</h2>\n<p>客户常常从网站上收到 AVIF 文件，却打不开。把文件转成 JPG，他们手里的每个软件都能打开这些图片了。</p>\n<p>转换前先问客户图片是用来做什么的。用来放网站的客户要 WebP，用来放文档的客户要 JPG。</p>\n<p>拿不准就两种格式都交付。JPG 文件到处能用，AVIF 原件在网上又小，客户可以按用途自己选。</p>\n<p>转好的文件起个清楚的名字，带上用途和日期。hero-photo.jpg 一看就知道是什么，download.avif 却什么都说明不了。</p>\n<p>交付时附一句简短的格式说明。一句话就能让客户不用再问，为什么每张图片都有两个副本。</p>\n<h2 id=\"avif-on-old-computer\">在旧电脑上转换 AVIF</h2>\n<p>旧电脑可能根本解码不了 AVIF，因为这个格式需要较新的浏览器。先更新浏览器，转换应该就能用了。</p>\n<p>浏览器实在更新不了，就把 AVIF 文件传到新一点的设备上再转换。手机或新一点的笔记本处理解码毫无压力。</p>\n<p>只有一张图片时，在新设备上用在线转换器是最快的办法。转好下载 JPG，再把 JPG 传回旧电脑就行。</p>\n<p>传回旧电脑后把转好的 JPG 留在上面。JPG 在旧机器的每个软件里都能打开，AVIF 文件却永远打不开。</p>\n<p>旧电脑经常用的话，考虑更新一下它的软件。现代浏览器能解决 AVIF 问题和其他很多问题，更新通常是免费的。</p>\n<h2 id=\"avif-for-portfolio\">为作品集转换 AVIF</h2>\n<p>作品集必须看起来完美，转换设置也要体现这一点。AVIF 图片用 90% 画质转成 JPG，客户放大看照片依然锐利。</p>\n<p>先选最强的图片，再按重要程度依次转换。主图最值得花心思，因为它决定了整个作品集的第一印象。</p>\n<p>每张图片转换后都检查一遍，不要只抽查。作品集图片不多，每张都很重要，全部快速看一遍是值得的。</p>\n<p>用 JPG 文件更新作品集网站，再在电脑和手机上测试。作品集里出现破损图片就等于丢了一个客户，所以每张图片都要确认能加载。</p>\n<p>把 AVIF 原件留在作品集文件夹里。客户要 WebP 或 AVIF 版时马上就能给，不用重新下载。</p>\n<p>整个流程就是：上传、选填充色、设画质、下载。想了解背后的原理，可以看<a href=\"/zh/blog/avif-zhuan-jpg-wanquan-zhinan/\">AVIF 转 JPG 完全指南</a>；正面对照可以看<a href=\"/zh/blog/avif-vs-jpg-duibi/\">AVIF vs JPG：新一代格式与通用格式对比</a>。如果要保留透明度，<a href=\"/zh/zhuanhuan-tupian/\">图片转换器</a>可以把 AVIF 转成 PNG。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"怎么一次转换多个下载的 AVIF 文件？","answer":"在文件选择器里一次选中多个 AVIF 文件，或者直接拖到上传区。点一下就能用同样的画质和填充色设置全部转换，整批打包成一个 ZIP 下载。每个文件独立转换，某个坏文件不会拖垮其余的。"},{"question":"浏览器解码不了 AVIF 文件怎么办？","answer":"把浏览器更新到最新版，AVIF 支持是在新版 Chrome、Edge、Firefox 和 Safari 里才加上的。还是失败就换个浏览器打开这个文件，确认它是不是真正的 AVIF。下载损坏的文件需要从源网站重新下载一份。"},{"question":"AVIF 照片用多少画质最合适？","answer":"85% 是大多数 AVIF 照片最好的默认值，大小和画质平衡得很好。要打印的图片用 90% 或更高，只有遇到文件大小限制时才逐步往下调。AVIF 照片本身画质很高，转换时很耐折腾。"},{"question":"下载前能检查转换后的 JPG 吗？","answer":"可以。点任意卡片上的“对比”，就能并排看到 AVIF 和 JPG。拖动分隔线，检查人脸、文字和颜色。第一次结果不对就微调画质或填充色再转一次，原件还留在队列里。"},{"question":"AVIF 转 JPG 在手机浏览器上能用吗？","answer":"可以。在手机浏览器里打开工具，从下载文件夹或相册里选 AVIF 文件，再下载转好的 JPG。转换就在手机上完成，文件会下载到你的设备里。手机上批量别贪多，大 AVIF 文件在手机上解码比较慢。"},{"question":"什么时候选 AVIF 转 JPG，而不是 AVIF 转 PNG？","answer":"目的地有明确要求，或者兼容性最重要时选 JPG，因为 JPG 到处能打开，文件也更小。需要保留透明度，或者打算反复编辑图片时选 PNG，因为 PNG 无损，还保留透明通道。"}];
